source("config.R"); source("R/utils.R"); load_project_packages(); ensure_dirs(); grid <- readRDS("data/interim/grid_0.5deg.rds"); mp <- assign_cells(readRDS("data/interim/microplastics_clean.rds"), grid); bio <- assign_cells(readRDS("data/interim/biodiversity_clean.rds"), grid); saveRDS(mp$data, "data/interim/microplastics_joined.rds"); saveRDS(bio$data, "data/interim/biodiversity_joined.rds"); readr::write_csv(tibble::tibble(dataset=c("microplastics","biodiversity"), assigned=c(mp$assigned,bio$assigned), unassigned=c(mp$unassigned,bio$unassigned)), "outputs/tables/spatial_join_summary.csv")
